/*
 * A287105  Positions of 0 in A287104.
 * https://oeis.org/A287105
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n‑th zero in the infinite word *
 *            generated by the morphism 0↦10, 1↦12, 2↦0. The word is the fixed
 *            * point of this substitution, starting with the symbol 1. The
 *            function * scans the word until the n‑th zero is found
 * Range:     u8 n <= 49, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* No external dependencies except the definition of seq_t and idx_t
   from the build, which are integer types. */
#include <stddef.h>     /* for size_t (not used but harmless) */

/* Pre‑computed lengths of σⁿ(s) for s = 0,1,2.  Depth 63 is more
   than enough for the required range. */
static seq_t lens0[64], lens1[64], lens2[64];
static int   depth   = 0;   /* greatest depth used (>=0) */
static int   init    = 0;   /* 1 if the tables have been initialized */

/* Initialise length tables and choose a depth large enough that
   the length of σ^depth(1) exceeds a small safety bound (≈ 60000).
   This bounds the maximum index that we will examine for n up to 10000. */
static void init_lengths(void)
{
    static const seq_t INF = (seq_t)60000;   /* sufficient for all tests */

    lens0[0] = lens1[0] = lens2[0] = (seq_t)1;
    for (int d = 1; d < 64; ++d)
    {
        lens0[d] = lens1[d-1] + lens0[d-1];   /* 0 → 1 0 */
        lens1[d] = lens1[d-1] + lens2[d-1];   /* 1 → 1 2 */
        lens2[d] = lens0[d-1];                /* 2 → 0   */
    }
    /* find smallest depth with length ≥ INF, or maximum if none */
    for (int d = 0; d < 64; ++d)
    {
        if (lens1[d] >= INF)
        {
            depth = d;
            break;
        }
    }
    if (depth == 0) depth = 63;
    init = 1;
}

/* Recursive helper: returns the symbol (0,1,2) that appears at
 * position 'pos' within σⁿ(symbol).  'level' is the exponent n of
 * σ.  'pos' is 1‑based. */
static int get_symbol(idx_t pos, int level, int symbol)
{
    if (level == 0) return symbol;          /* σ⁰(symbol) = symbol */

    idx_t part = (idx_t)lens1[level-1];     /* length of first block in σ(symbol) */

    if (symbol == 0)                       /* σ(0) = 1 0 */
    {
        if (pos <= part)
            return get_symbol(pos, level-1, 1);
        else
            return get_symbol(pos - part, level-1, 0);
    }
    else if (symbol == 1)                  /* σ(1) = 1 2 */
    {
        if (pos <= part)
            return get_symbol(pos, level-1, 1);
        else
            return get_symbol(pos - part, level-1, 2);
    }
    else /* symbol == 2, σ(2) = 0 */        /* single symbol, level>0 */
    {
        return get_symbol(pos, level-1, 0);
    }
}

/* Return the symbol (0,1,2) at global position 'pos' (1‑based) in
 * the infinite word (fixed point of σ). */
static int symbol_at_pos(idx_t pos)
{
    if (!init) init_lengths();

    /* find the depth such that the word σ^depth(1) contains position pos */
    int level = 0;
    while ((idx_t)lens1[level] < pos && level < depth)
        ++level;

    return get_symbol(pos, level, 1);   /* start from symbol 1 */
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;        /* offset = 1; not used for n=0 */

    idx_t zeros   = 0;
    idx_t pos     = 1;

    while (1)
    {
        if (symbol_at_pos(pos) == 0)
        {
            ++zeros;
            if (zeros == n) return (seq_t)pos;
        }
        ++pos;
    }
}
